// Legacy parity (T020): compares our parser + rules against JSON generated by running the legacy
// PV.Core code (tools/legacy-parity) over the same archive. Legacy mode must match exactly; corrected
// mode may differ only where a documented fix applies (D-1 amounts, D-3/D-4 → 2 breaks instead of 7).
// Archive: $LEGACY_ARCHIVE or the vendored data/legacy-pv/archive (skipped when absent).
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { test } from 'node:test';
import { loadArchiveFacts, type ArchiveFacts } from '../archive.js';
import { decCmp, decEq } from '../decimal.js';
import { readLegacySeed, seedAccountRefs } from '../legacy-seed.js';
import { defaultSeedDir } from '../migrate-legacy.js';
import { buildRuleContext, confirmationAmount, positionChecksForAll, selectEffectiveStatement, type RuleMode } from '../rules.js';

const repo = resolve(import.meta.dirname, '../../..');
const archive = process.env.LEGACY_ARCHIVE ?? join(repo, 'data/legacy-pv/archive');
const fixtures = join(repo, 'fixtures/custody/legacy');
const skip = !existsSync(archive) && `archive not found at ${archive} (set LEGACY_ARCHIVE)`;
const load = <T>(name: string): T => JSON.parse(readFileSync(join(fixtures, name), 'utf8'));

interface LegacyStatement {
  file: string; function: string; statementDate: string; safe: string; fileSeq: number; effective: boolean;
  lines: { isin: string; qty: string; qtyType: string; price: string; ccy: string; marketValue: string; marketValueGbp: string }[];
}
interface LegacyConfirmation {
  file: string; folder: string; mtType: number; seme: string; prev: string | null; function: string; tradeDate: string; settleDate: string;
  isin: string; qty: string; safe: string; amountRaw: string | null; amount: string | null; direction: 'REC' | 'DEL';
}
interface LegacyBreak { accountId: number; date: string; isin: string; previousQty: string; settledNet: string; expectedQty: string; reportedQty: string; difference: string }

let facts: ArchiveFacts | undefined;
const getFacts = () => (facts ??= loadArchiveFacts(archive));

test('MT535 statements parse exactly as legacy SwiftParser', { skip }, () => {
  const legacy = load<{ mt535Files: number; parseErrors: number; statements: LegacyStatement[] }>('statements.json');
  const ours = new Map(getFacts().files.flatMap(f => (f.kind === 'statement' ? [[f.entry.fileName, f] as const] : [])));
  assert.equal(legacy.parseErrors, 0);
  assert.equal(legacy.statements.length, 3073);
  assert.equal(ours.size, legacy.statements.length);
  for (const l of legacy.statements) {
    const f = ours.get(l.file);
    assert.ok(f, l.file);
    const s = f.statement;
    assert.equal(s.functionCode, l.function, l.file);
    assert.equal(s.statementDate, l.statementDate, l.file);
    assert.equal(s.safeRaw, l.safe, l.file);
    assert.equal(f.entry.fileSeq, l.fileSeq, l.file);
    assert.equal(s.lines.length, l.lines.length, l.file);
    s.lines.forEach((ln, i) => {
      const x = l.lines[i];
      const at = `${l.file} ${x.isin}`;
      assert.equal(ln.isin, x.isin, at);
      assert.equal(ln.qtyType, x.qtyType, at);
      assert.equal(ln.ccy, x.ccy, at);
      assert.ok(decEq(ln.qty, x.qty), `${at} qty ${ln.qty} vs ${x.qty}`);
      assert.ok(decEq(ln.price, x.price), `${at} price ${ln.price} vs ${x.price}`);
      assert.ok(decEq(ln.marketValue, x.marketValue), `${at} mv ${ln.marketValue} vs ${x.marketValue}`);
      // Legacy stores a missing 19A::HOLD as 0 (D-8); we keep null.
      assert.ok(decEq(ln.reportingValue ?? '0', x.marketValueGbp), `${at} gbp ${ln.reportingValue} vs ${x.marketValueGbp}`);
    });
  }
});

test('effective statement: legacy mode = highest file seq; corrected differs only for RPLC (D-4) or identical DUPL resends', { skip }, () => {
  const legacy = load<{ statements: LegacyStatement[] }>('statements.json').statements;
  const groups = new Map<string, LegacyStatement[]>();
  for (const s of legacy) {
    const k = `${s.safe.replace(/^0+/, '')}|${s.statementDate}`;
    groups.set(k, [...(groups.get(k) ?? []), s]);
  }
  let rplcDiffs = 0;
  for (const [k, day] of groups) {
    const cands = day.map(s => ({ functionCode: s.function, fileSeq: s.fileSeq, file: s.file }));
    const expected = day.find(s => s.effective)!.file;
    assert.equal(selectEffectiveStatement(cands, 'legacy')!.file, expected, k);
    const corrected = selectEffectiveStatement(cands, 'corrected')!.file;
    if (corrected !== expected) {
      const ours = day.find(s => s.file === corrected)!, theirs = day.find(s => s.file === expected)!;
      if (ours.function === 'RPLC') rplcDiffs++;
      // Otherwise corrected keeps the original NEWM over a resent duplicate: content must be identical.
      else assert.ok(theirs.function.endsWith('/DUPL') && JSON.stringify(ours.lines) === JSON.stringify(theirs.lines), k);
    }
  }
  assert.ok(rplcDiffs >= 1, 'archive contains at least one RPLC-before-NEWM/DUPL day');
});

test('MT54x confirmations parse as legacy; amounts differ only for one-digit fractions (D-1)', { skip }, () => {
  const legacy = load<{ mt54xFiles: number; confirmations: LegacyConfirmation[] }>('confirmations.json');
  const ours = new Map(getFacts().files.flatMap(f => (f.kind === 'confirmation' ? [[`${f.entry.folder}/${f.entry.fileName}`, f] as const] : [])));
  assert.equal(legacy.confirmations.length, 2971);
  assert.equal(ours.size, legacy.confirmations.length);
  let d1 = 0;
  for (const l of legacy.confirmations) {
    const f = ours.get(`${l.folder}/${l.file}`);
    assert.ok(f, l.file);
    const c = f.confirmation;
    assert.equal(c.mtType, l.mtType, l.file);
    assert.equal(c.seme, l.seme, l.file);
    assert.equal(c.prevRef, l.prev, l.file);
    assert.equal(c.functionCode, l.function, l.file);
    assert.equal(c.tradeDate, l.tradeDate, l.file);
    assert.equal(c.settleDate, l.settleDate, l.file);
    assert.equal(c.isin, l.isin, l.file);
    assert.ok(decEq(c.qty, l.qty), l.file);
    assert.equal(c.safeRaw, l.safe, l.file);
    assert.equal(c.direction === 'RECEIVE' ? 'REC' : 'DEL', l.direction, l.file);
    assert.equal(c.amountRaw, l.amountRaw, l.file);
    if (l.amount === null) continue;
    assert.ok(decEq(confirmationAmount(c.amountRaw, 'legacy')!, l.amount), `${l.file} legacy amount`);
    if (!decEq(confirmationAmount(c.amountRaw, 'corrected')!, l.amount)) {
      d1++;
      assert.match(l.amountRaw!, /,\d$/, `${l.file}: only one-digit fractions may differ`);
    }
  }
  assert.ok(d1 >= 1, 'archive contains a D-1 one-decimal amount');
});

const breaksIn = (mode: RuleMode) => {
  const f = getFacts();
  const outcomes = positionChecksForAll(buildRuleContext(f.statements, f.confirmations, mode), seedAccountRefs(readLegacySeed(defaultSeedDir())));
  return outcomes.flatMap(o => o.rows.map(r => ({ accountId: o.accountId, date: o.date, ...r })))
    .sort((a, b) => a.accountId - b.accountId || a.date.localeCompare(b.date) || a.isin.localeCompare(b.isin));
};

test('legacy-mode position checks reproduce the legacy 7 breaks exactly', { skip }, () => {
  const legacy = load<{ breaks: LegacyBreak[]; breakCount: number }>('position-checks.json');
  assert.equal(legacy.breakCount, 7);
  const ours = breaksIn('legacy');
  assert.equal(ours.length, legacy.breaks.length);
  ours.forEach((b, i) => {
    const x = legacy.breaks[i];
    const at = `${x.accountId} ${x.date} ${x.isin}`;
    assert.deepEqual([b.accountId, b.date, b.isin], [x.accountId, x.date, x.isin]);
    for (const k of ['previousQty', 'settledNet', 'expectedQty', 'reportedQty', 'difference'] as const)
      assert.equal(decCmp(b[k], x[k]), 0, `${at} ${k}: ${b[k]} vs ${x[k]}`);
  });
});

test('corrected-mode position checks report the 2 genuine breaks', { skip }, () => {
  const ours = breaksIn('corrected').map(b => `${b.accountId} ${b.isin} ${b.date} ${b.difference}`);
  assert.deepEqual(ours, ['2001 GB00ZZ011962 2026-07-17 800.00', '2074 GB00ZZ000908 2026-07-31 900.00']);
});
